            seen.add(link);
            const numRaw = pick(el, config.chapters.number) ?? pick(el, selectorOf(config.chapters.link));
            const num = numRaw ? (numRaw.match(/[\d.]+/)?.[0] ?? numRaw) : null;
            out.push({
